const PAGE_SIZE = 6;
let currentCat = "all";
let currentQuery = "";
let visibleCount = PAGE_SIZE;

// ── RENDER HELPERS ────────────────────────────────────────────────────
function avatarClass(c) { return c || ""; }

function renderCard(post) {
  return `
  <article class="post-card" data-id="${post.id}" data-categories="${post.category}" data-title="${post.title.toLowerCase()}">
    <div class="post-card-img" style="background:${post.gradient}">
      <span class="img-initials">${post.imgLabel}</span>
    </div>
    <div class="post-body">
      <div class="post-tag-row">
        <span class="post-tag">${post.categoryLabel}</span>
        <span class="post-date">${post.date}</span>
      </div>
      <h3 class="post-title">${post.title}</h3>
      <p class="post-excerpt">${post.excerpt}</p>
      <div class="post-author">
        <span class="avatar-sm ${avatarClass(post.authorColor)}" style="background:${post.authorColor ? '' : '#0072F5'}">${post.authorInitials}</span>
        <span class="post-author-name">${post.author}</span>
      </div>
    </div>
  </article>`;
}

function filteredPosts() {
  return ALL_POSTS.filter(p => {
    const catMatch = currentCat === "all" || p.category === currentCat;
    const qMatch = !currentQuery || p.title.toLowerCase().includes(currentQuery) || p.excerpt.toLowerCase().includes(currentQuery);
    return catMatch && qMatch;
  });
}

function renderGrid() {
  const grid = document.getElementById("postsGrid");
  const noRes = document.getElementById("noResults");
  const btn = document.getElementById("showMoreBtn");
  const feat = document.getElementById("featuredSection");
  const posts = filteredPosts();
  const slice = posts.slice(0, visibleCount);

  grid.innerHTML = slice.map(renderCard).join("");

  if (posts.length === 0) {
    noRes.style.display = "block";
    grid.style.display = "none";
  } else {
    noRes.style.display = "none";
    grid.style.display = "grid";
  }

  btn.disabled = visibleCount >= posts.length;
  btn.style.display = posts.length === 0 ? "none" : "";

  // Hide featured section when filtering by specific category or searching
  const filtering = currentCat !== "all" || currentQuery !== "";
  feat.style.display = filtering ? "none" : "";
}

// ── EVENTS ────────────────────────────────────────────────────────────
// Category pills
