  const pill = e.target.closest(".pill");
  if (!pill) return;
  document.querySelectorAll(".pill").forEach(p => p.classList.remove("active"));
  pill.classList.add("active");
  currentCat = pill.dataset.cat;
  visibleCount = PAGE_SIZE;
  renderGrid();
});

// Search
